(() => {
 const workspace = location.hash.startsWith('#/');
 window.addEventListener('hashchange', () => {if(location.hash.startsWith('#/') !== workspace) location.reload();});
 if(workspace){document.getElementById('home').remove();document.title='Vibe — Creative workspace';const script=document.createElement('script');script.src='runtime/workspace.js';document.body.append(script);return;}
 let brand='lawyer',createdId=null;
 const design=document.getElementById('home-design'),frame=document.getElementById('home-preview-frame');frame.src=frame.dataset.src;
 const updatePreview=()=>{
  const name=brand==='lawyer'?'Someone.lawyer':'AI Company Market';
  const file=brand==='lawyer'?'Someone-Lawyer-All-Designs.html':'AI-Company-Market-All-Designs.html';
  const url=file+'?design='+design.value+'#/discover';frame.src=url;frame.title=name+' live design preview';
  document.getElementById('home-preview-link').href=url;
  document.getElementById('home-preview-label').textContent=name.toUpperCase()+' / '+design.selectedOptions[0].textContent.slice(5).toUpperCase();
  document.querySelectorAll('[data-home-brand]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.homeBrand===brand)));
 };
 document.querySelectorAll('[data-home-brand]').forEach(button=>button.addEventListener('click',()=>{brand=button.dataset.homeBrand;updatePreview();}));design.addEventListener('change',updatePreview);
 const form=document.getElementById('home-brief-form'),idea=document.getElementById('home-idea'),status=document.getElementById('home-brief-status');
 try{idea.value=localStorage.getItem('vibe-home-idea')||'';}catch{}
 idea.addEventListener('input',()=>{try{localStorage.setItem('vibe-home-idea',idea.value);}catch{}});
 form.addEventListener('submit',async event=>{
  event.preventDefault();const prompt=idea.value.trim();if(!prompt){idea.focus();return;}
  const button=form.querySelector('button');button.disabled=true;status.textContent='Creating your project…';
  try{
   const bootstrap=await fetch('/api/bootstrap');if(!bootstrap.ok)throw Error('Open this page through the local Vibe server to create a project.');const data=await bootstrap.json();
   const post=async(path,body)=>{const response=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':data.token},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw Error(result.error||'Could not save your project.');return result;};
   if(!createdId){const project=await post('project',{name:prompt.slice(0,70),description:prompt,category:document.body.dataset.edition==='law'&&data.state.categories.some(c=>c.id==='legal')?'legal':null});createdId=project.id;}
   await post('draft',{project:createdId,draft:{objective:prompt,prompt,context:document.body.dataset.edition==='law'?'Vibe Law: a project for law students, lawyers or legal teams.':'Vibe One: a creative product or website project.'}});
   try{localStorage.removeItem('vibe-home-idea');}catch{}
   location.hash='/project/'+createdId+'/prompt';
  }catch(error){status.textContent=error.message;button.disabled=false;}
 });
})();

/* Vibe One / Vibe Law product front door. */
(() => {
 if(location.hash.startsWith('#/')) return;
 const $=s=>document.querySelector(s);
 const sun='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>';
 const moon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M20 15.4A8.5 8.5 0 0 1 8.6 4 8.5 8.5 0 1 0 20 15.4Z"/></svg>';
 let edition='one',theme='dark';try{edition=(new URLSearchParams(location.search).get('edition')||localStorage.getItem('vibe-edition'))==='law'?'law':'one';theme=localStorage.getItem('vibe-home-theme')|| (matchMedia('(prefers-color-scheme: light)').matches?'light':'dark');}catch{}
 $('.home-nav').innerHTML=`<a class="home-logo" href="#top" aria-label="Vibe homepage"><svg viewBox="0 0 28 28" fill="none" stroke="currentColor" stroke-width="2"><path d="m3 5 7 18L17 5M12 5l7 18 7-18"/></svg><span id="vibe-wordmark">Vibe One</span><small>V1</small></a><nav aria-label="Main navigation"><details class="home-product-menu"><summary>Our tools <span aria-hidden="true">⌄</span></summary><div><button data-edition="one"><strong>Vibe One</strong><span>For ideas, products & independent creators</span></button><button data-edition="law"><strong>Vibe Law</strong><span>For law students, lawyers & legal teams</span></button><a href="#editions">Compare the two tools ↗</a></div></details><a href="#workspace-section">Features</a><a href="#designs">Explore the builder</a><a href="#workflow">How it works</a></nav><div class="home-nav-actions"><a class="home-workspace-link" href="#/dashboard">Workspace ↗</a><button id="home-theme" class="home-theme" type="button"></button><a class="home-button" href="#start">Start free ↗</a><details class="home-mobile-nav"><summary aria-label="Open navigation">☰</summary><div><a href="#editions">Vibe One & Vibe Law</a><a href="#workspace-section">Features</a><a href="#designs">Explore the builder</a><a href="#workflow">How it works</a><a href="#questions">Questions</a><a href="#/dashboard">Open workspace ↗</a></div></details></div>`;
 $('.home-nav').insertAdjacentHTML('afterend','<div class="home-promo"><span><b>YOUR NEXT IDEA STARTS HERE</b> Free local workspace. Two tools. Endless first drafts.</span><a href="#start">Make your first project <span aria-hidden="true">↗</span></a></div>');
 $('#workspace-section').insertAdjacentHTML('beforebegin',`<section id="editions" class="home-section home-editions"><div class="home-section-head"><div><div class="home-kicker">Created by Law Tech Labs</div><h2>One creative foundation.<br><em>Two ways to make it yours.</em></h2></div><p>Choose the starting point that fits your work. Both editions share the same project, prompt and design workspace.</p></div><div class="home-edition-grid"><article><span class="home-edition-tag">FOR THE IDEAS YOU CAN'T LEAVE ALONE</span><h3>Vibe <em>One.</em></h3><p>Your space to shape websites, products and new businesses. Bring the idea. Build the brief. Find the direction.</p><ul><li>Creators & independent founders</li><li>Product ideas & website concepts</li><li>Flexible project briefs & AI workflows</li></ul><button class="home-button secondary" data-edition="one">Explore Vibe One ↗</button></article><article><span class="home-edition-tag">FOR THE NEXT GENERATION OF LEGAL WORK</span><h3>Vibe <em>Law.</em></h3><p>A focused starting point for legal study and practice. Organise research, shape legal technology ideas and develop useful workflows.</p><ul><li>Law students & educators</li><li>Lawyers & legal teams</li><li>Research briefs & legal technology projects</li></ul><button class="home-button secondary" data-edition="law">Explore Vibe Law ↗</button></article></div></section>`);
 $('#designs .home-section-head').innerHTML='<div><div class="home-kicker">A working example, not a blank canvas</div><h2>Try a direction.<br><em>Make it your own.</em></h2></div><p>Start with a complete sample project. Choose its design variation, explore the pages, then take that exact selection into the builder to refine it.</p>';
 $('.home-show-controls').insertAdjacentHTML('beforebegin','<ol class="home-builder-steps"><li><b>01</b> Choose a sample project</li><li><b>02</b> Pick a design direction</li><li><b>03</b> Open it in the builder</li></ol>');
 $('.home-show-controls').insertAdjacentHTML('afterend','<div class="home-builder-entry"><div><strong id="home-selection">Someone.lawyer · Inference Utility</strong><p>Full sample project · landing page, catalogue and inner pages included</p></div><a id="home-builder-link" class="home-button" href="design-studio.html?brand=lawyer&design=6&page=discover&project=lawyer">Customise in builder ↗</a></div>');
 const syncBuilder=()=>{const active=$('[data-home-brand][aria-pressed="true"]');const brand=active?.dataset.homeBrand||'lawyer';const design=$('#home-design').value;$('#home-builder-link').href='design-studio.html?brand='+brand+'&design='+design+'&page=discover&project='+brand;$('#home-selection').textContent=(brand==='lawyer'?'Someone.lawyer':'AI Company Market')+' · '+$('#home-design').selectedOptions[0].textContent.slice(5);};
 $('#home-preview-frame').addEventListener('load',()=>{try{const loaded=new URL($('#home-preview-frame').contentWindow.location.href);const variation=Number(loaded.searchParams.get('design'));if(variation>=1&&variation<=7){$('#home-design').value=String(variation);$('#home-preview-link').href=loaded.href;syncBuilder();$('#home-preview-label').textContent=$('#home-selection').textContent.toUpperCase();}}catch{}});document.querySelectorAll('[data-home-brand]').forEach(b=>b.addEventListener('click',syncBuilder));$('#home-design').addEventListener('change',syncBuilder);syncBuilder();
 $('#start').insertAdjacentHTML('beforebegin','<aside class="home-offer"><div><span class="home-kicker">LESS SETUP. MORE MOMENTUM.</span><h2>Your first project.<br>Your next possibility.</h2><p>Start free in your local workspace. No sign-up required. Connect your own model when you’re ready.</p><small>Model provider usage is billed separately by your provider.</small></div><a class="home-button" href="#start">Start creating for free ↗</a></aside>');
 $('.home-footer').outerHTML=`<footer class="home-footer home-company-footer"><div class="home-footer-brand"><a class="home-logo" href="#top">Vibe<span class="home-footer-by">by Law Tech Labs</span></a><p>A thoughtful workspace for ideas, people<br>and the things they’re ready to build.</p><small>V1 · Built for your next version.</small></div><div><strong>Products</strong><a href="index.html?edition=one#top">Vibe One</a><a href="index.html?edition=law#top">Vibe Law</a><a href="design-studio.html">Design builder ↗</a></div><div><strong>Explore</strong><a href="#workspace-section">Features</a><a href="#designs">Sample projects</a><a href="#questions">Questions & data use</a></div><div><strong>Get started</strong><a href="#start">Start free</a><a href="#/dashboard">Your workspace ↗</a><a href="#/connections">Model connections ↗</a></div><div class="home-footer-bottom"><span>© ${new Date().getFullYear()} Law Tech Labs · Vibe One & Vibe Law</span><span>Created with intention. Built to evolve.</span><a href="#top">Back to top ↑</a></div></footer>`;
 const setTheme=()=>{document.documentElement.dataset.homeTheme=theme;const dark=theme==='dark';$('#home-theme').innerHTML=dark?sun:moon;$('#home-theme').setAttribute('aria-label','Switch to '+(dark?'light':'dark')+' mode');$('#home-theme').title='Switch to '+(dark?'light':'dark')+' mode';$('#home-theme').setAttribute('aria-pressed',String(dark));try{localStorage.setItem('vibe-home-theme',theme);}catch{}};
 $('#home-theme').onclick=()=>{theme=theme==='dark'?'light':'dark';setTheme();};setTheme();
 const setEdition=(next,interacted=false)=>{edition=next;document.body.dataset.edition=edition;const law=edition==='law';$('#vibe-wordmark').textContent=law?'Vibe Law':'Vibe One';document.title=(law?'Vibe Law':'Vibe One')+' — by Law Tech Labs';$('.home-hero .home-kicker').textContent=law?'A creative workspace for legal minds':'A creative workspace for your next idea';$('.home-hero h1').innerHTML=law?'Legal minds.<br>Fresh ideas.<br><em>New possibilities.</em>':'Big ideas.<br>Less friction.<br><em>More making.</em>';$('.home-hero p').textContent=law?'For law students, lawyers and legal teams. Organise your research, shape your brief and explore what better legal tools could look like.':'Bring your brief, your files and your favourite model. Turn a first thought into a considered design, with a workspace that keeps everything together.';$('#home-idea').placeholder=law?'A research workspace for my legal studies…':'A thoughtful website for my next idea…';document.querySelectorAll('[data-edition]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.edition===edition)));if(interacted){const editionUrl=new URL(location.href);editionUrl.searchParams.set('edition',edition);history.replaceState(null,'',editionUrl);document.querySelector('[data-home-brand="'+(law?'lawyer':'market')+'"]').click();document.querySelectorAll('.home-nav details').forEach(d=>d.open=false);$('#top').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}try{localStorage.setItem('vibe-edition',edition);}catch{}};
 document.querySelectorAll('[data-edition]').forEach(b=>b.addEventListener('click',()=>setEdition(b.dataset.edition,true)));setEdition(edition);
 document.querySelectorAll('.home-mobile-nav a').forEach(a=>a.addEventListener('click',()=>{$('.home-mobile-nav').open=false;}));
 document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.home-nav details').forEach(d=>d.open=false);});
})();
